public class ContaSegura { private double saldo; private boolean ativa=true; public double getSaldo(){return saldo;} public void depositar(double v){if(ativa&&v>0)saldo+=v;} public boolean sacar(double v){if(ativa&&v>0&&v<=saldo){saldo-=v;return true;}return false;} public void desativar(){ativa=false;} public static void main(String[] a){ContaSegura c=new ContaSegura();c.depositar(100);System.out.println(c.sacar(50)+" "+c.getSaldo());}}
